// Reading the trigger lookup on a trigger node that never fired THROWS in
// this n8n version (confirmed via live E2E testing: running this workflow
// via Manual Trigger alone, with Execute Workflow Trigger never executing,
// crashed here) — wrap in try/catch so both "never executed" and "executed
// with zero items" degrade to the same safe default.
let trigger = {};
try {
  const triggerItems = $('When Executed by Another Workflow').all();
  trigger = triggerItems.length ? triggerItems[0].json : {};
} catch (e) { trigger = {}; }
const asOfDate = trigger.asOfDate || new Date().toISOString().slice(0, 10);
const runType = trigger.runType || 'LIVE';
return [{ json: { asOfDate, runType } }];

function isNumber(v) { return typeof v === 'number' && Number.isFinite(v); }
function fmt(v, d) { return isNumber(v) ? v.toFixed(d) : 'unknown'; }

// Runs once for the WHOLE batch — one item per Top 10 pick arrives here
// from "Load Top 10 Scanner Results". Must loop $input.all() explicitly
// (same bug pattern found and fixed across every multi-item Code node in
// this project — confirmed via live E2E testing).

const items = $input.all();
const out = [];

for (const item of items) {
  const r = item.json;

  const prompt = [
    'You are assisting a quantitative EGX (Egyptian Exchange) stock scanner.',
    'Base your answer ONLY on the technical/quantitative data below — you have',
    'no real-time market access, no news, and no information beyond what is given.',
    '',
    'Stock: ' + r.symbol + ' (' + (r.name || 'unknown') + ')',
    'Scanner setup type: ' + r.setup_type + ' (overall rank ' + r.overall_rank + ' of the day\'s Top 10)',
    'Overall algorithmic score: ' + fmt(r.overall_score, 1) + '/100',
    'Sub-scores — Breakout: ' + fmt(r.breakout_score, 1) + ', Momentum: ' + fmt(r.momentum_score, 1) +
      ', Pullback: ' + fmt(r.pullback_score, 1) + ', Reversal: ' + fmt(r.reversal_score, 1),
    'RSI14: ' + fmt(r.rsi14, 1) + ', MACD histogram: ' + fmt(r.macd_histogram, 4),
    'Trend — short-term: ' + (r.short_term_trend || 'unknown') + ', medium-term: ' + (r.medium_term_trend || 'unknown') +
      ', long-term: ' + (r.long_term_trend || 'unknown'),
    'Entry: ' + fmt(r.entry_price, 2) + ', Target 1: ' + fmt(r.target1, 2) +
      ' (potential gain ' + fmt(r.target1_gain_pct, 2) + '%), Invalidation/stop: ' + fmt(r.invalidation_price, 2) +
      ', Risk:Reward to Target 1: ' + fmt(r.risk_reward_t1, 2),
    'Estimated days to Target 1 (rough ATR-based projection from this stock\'s own volatility, not a guarantee): ' +
      (r.target1_estimated_days != null ? r.target1_estimated_days : 'unknown'),
    '',
    'Provide: (1) your own estimated probability (0-100) that price reaches Target 1',
    'within that estimated-days window, given ONLY this data, (2) a 0-100',
    'conviction/rank score for this setup\'s overall quality relative to other similar',
    'setups, (3) a brief 1-2 sentence rationale. Be honest about uncertainty — this is',
    'a probability estimate from limited technical data, not a guarantee.',
  ].join('\n');

  const requestBody = {
    model: 'claude-sonnet-5',
    max_tokens: 500,
    tools: [{
      name: 'provide_assessment',
      description: 'Provide a structured probability and rank assessment for this stock setup.',
      input_schema: {
        type: 'object',
        properties: {
          target1_probability_pct: {
            type: 'number',
            description: 'Estimated probability (0-100) of reaching Target 1 within the estimated-days window.',
          },
          rank_score: {
            type: 'number',
            description: '0-100 conviction score for this setup, used to rank it against the other Top 10 candidates.',
          },
          reasoning: { type: 'string', description: '1-2 sentence rationale.' },
        },
        required: ['target1_probability_pct', 'rank_score', 'reasoning'],
      },
    }],
    tool_choice: { type: 'tool', name: 'provide_assessment' },
    messages: [{ role: 'user', content: prompt }],
  };

  out.push({ json: {
    scannerResultId: r.scanner_result_id,
    symbol: r.symbol,
    requestBodyJson: JSON.stringify(requestBody),
  } });
}

return out;

function isNumber(v) { return typeof v === 'number' && Number.isFinite(v); }
function clamp(v, lo, hi) { return Math.min(hi, Math.max(lo, v)); }

// Runs once for the WHOLE batch. itemMatching(i) pairs each response back
// to the request that produced it (same pairing pattern used everywhere in
// this project — confirmed via live E2E testing to be the only reliable
// way to line up parallel per-item chains).

const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  let original;
  try { original = $('Build Prompt').itemMatching(i).json; } catch (e) { continue; }
  const row = items[i].json;

  // ANTHROPIC_API_KEY unset/invalid, rate limited, or any other API error
  // all land here the same way: no tool_use block found -> skip this row
  // rather than writing garbage. Never throws the workflow.
  const content = Array.isArray(row.content) ? row.content : [];
  const toolUse = content.find((c) => c && c.type === 'tool_use' && c.name === 'provide_assessment');
  const input = toolUse ? toolUse.input : null;

  if (!input || !isNumber(input.target1_probability_pct) || !isNumber(input.rank_score)) {
    out.push({ json: { scannerResultId: original.scannerResultId, _skip: true } });
    continue;
  }

  out.push({ json: {
    scannerResultId: original.scannerResultId,
    targetProbabilityPct: clamp(input.target1_probability_pct, 0, 100),
    rankScore: clamp(input.rank_score, 0, 100),
    reasoning: typeof input.reasoning === 'string' ? input.reasoning.slice(0, 2000) : null,
    _skip: false,
  } });
}

return out;

// Runs once for the WHOLE batch — sorts whichever picks got a successful
// assessment by rank_score and assigns 1..N. A pick that failed/was
// skipped simply never reaches here (filtered by "Has Assessment?"), so
// ai_rank is only ever assigned among picks that actually got assessed.
const items = $input.all().map((i) => i.json);
const sorted = [...items].sort((a, b) => b.rankScore - a.rankScore);
const rankMap = new Map(sorted.map((it, idx) => [it.scannerResultId, idx + 1]));
return items.map((it) => ({ json: { ...it, aiRank: rankMap.get(it.scannerResultId) } }));

return [{ json: {
  workflow: '17-egx-ai-assessment',
  finishedAt: new Date().toISOString(),
} }];
